def extract_output(body):
    m = re.search(r'<div class="output-area" id="output">(.*?)</div>', body, re.S)
    if not m:
        return "(no output-area found) len="+str(len(body))
    txt = re.sub(r'<[^>]+>', '', m.group(1)).strip()
    return txt[:500]

